export interface TierStay {
  name: string
  image: string
  amenities: string[]
}

export interface ItineraryDay {
  day: number
  title: string
  description: string
  accommodation: string
  meals: string
  insiderFact?: string
  // "Location" column for the optional "Itinerary at a Glance" summary table —
  // the "Focus" column is just `title`, so no separate field is needed for that.
  location?: string
  accommodationByTier?: {
    trail?: TierStay
    reserve?: TierStay
    sovereign?: TierStay
  }
  // Separate two-tier variant for packages using Luxury/Ultra-Luxury naming
  // (e.g. the family safari line) instead of the Wilderness Trail/Reserve/
  // Sovereign vocabulary — kept independent rather than overloading
  // accommodationByTier with mismatched tier labels.
  accommodationByFamilyTier?: {
    luxury?: TierStay
    ultraLuxury?: TierStay
  }
}

export interface PricingTierRow {
  pax: number
  // Optional so existing single-season packages need no changes; a package
  // that wants a High/Low season toggle just tags every row with a season —
  // PriceTierSwitcher only renders the toggle when it sees more than one.
  season?: 'high' | 'low'
  // trail, reserve, and sovereign are all optional — a package supplies
  // whichever tiers it actually offers; PriceTierSwitcher only renders
  // buttons for tiers that are present.
  trail?: number
  reserve?: number
  sovereign?: number
}

export interface FamilyPricingRow {
  season: 'high' | 'low'
  familySize: number
  luxury: number
  ultraLuxury: number
}

export interface SafariPackage {
  slug: string
  name: string
  duration: number
  destinations: string[]
  type: 'wildlife' | 'trekking' | 'beach' | 'combination'
  priceFrom: number
  groupSize: { min: number; max: number }
  highlights: string[]
  itinerary: ItineraryDay[]
  included: string[]
  excluded: string[]
  heroImage: string
  gallery: string[]
  badge?: 'bestseller' | 'new' | 'popular'
  bestFor: string[]
  // Optional per-pax x tier pricing grid. Absent on most packages — the page
  // falls back to the flat `priceFrom` display when this isn't populated.
  pricingTiers?: PricingTierRow[]
  // Set when pricingTiers was derived from priceFrom via a markup formula
  // rather than confirmed real rates — the page shows a "confirm with our
  // team" note when true.
  pricingTiersProvisional?: boolean
  includedCategorized?: {
    transfers?: string[]
    accommodationMeals?: string[]
    guidingGameDrives?: string[]
  }
  excludedCategorized?: string[]
  notes?: string[]
  // Two-tier (Luxury / Ultra-Luxury) x season pricing grid, priced by family
  // size rather than raw pax count — used by the family safari package only.
  familyPricing?: FamilyPricingRow[]
  faq?: { q: string; a: string }[]
  // Intro paragraphs shown directly under the hero, above the quick-info row.
  overview?: string[]
  // The short "why book with us" one-liner shown as a quick-info chip.
  tagline?: string
  // The "Best time to travel" line shown as a quick-info chip.
  bestTimeToTravel?: string
  // "Why This Itinerary Is Different" section, rendered after Highlights.
  whyDifferent?: { heading: string; paragraphs: string[] }
  // "Destination Highlights" / "Photography Highlights" cards, rendered after whyDifferent.
  // `heading` carries the section's own title since docs vary it ("Destination Highlights",
  // "Photography Highlights", "Highlights") rather than assuming one fixed label.
  destinationHighlights?: { heading: string; items: { title: string; text: string }[] }
  // Overrides for the auto-generated <title>/<meta description> when a package
  // supplies its own SEO-authored copy instead of relying on the name/highlights fallback.
  metaTitle?: string
  metaDescription?: string
}

